import { readFileSync } from 'fs'

import { load } from 'cheerio'
import { describe, expect, test, vi } from 'vitest'

import { loadPages } from '@/frame/lib/page-data'
import { get } from '@/tests/helpers/e2etest'

type Page = {
  autogenerated?: string
  fullPath: string
  relativePath: string
  permalinks: Array<{ href: string }>
  versions: {
    feature?: string | string[]
    [key: string]: string | string[] | undefined
  }
}

const pageList: Page[] = await loadPages(undefined, ['en'])

// CI sets AUTOGENERATED_RENDER_ALL in the merge queue and on PRs that change pipeline code or output.
// Otherwise, render a fixed set of pages per generator to keep local runs and PRs fast.
const RENDER_ALL = process.env.AUTOGENERATED_RENDER_ALL === 'true'

// Paths are relative to content/. Generators not listed here render every page.
// Pick pages that use the generator's main page layout, not index pages.
const PINNED_PAGES: Record<string, string[]> = {
  'codeql-cli': [
    'code-security/reference/code-scanning/codeql/codeql-cli-manual/database-analyze.md',
    'code-security/reference/code-scanning/codeql/codeql-cli-manual/database-create.md',
    'code-security/reference/code-scanning/codeql/codeql-cli-manual/github-merge-results.md',
  ],
  'github-apps': [
    'rest/authentication/endpoints-available-for-github-app-installation-access-tokens.md',
    'rest/authentication/permissions-required-for-fine-grained-personal-access-tokens.md',
    'rest/authentication/permissions-required-for-github-apps.md',
  ],
  graphql: [
    'graphql/overview/breaking-changes.md',
    'graphql/overview/changelog/2025.md',
    'graphql/reference/repos.md',
  ],
  rest: ['rest/actions/workflow-runs.md', 'rest/issues/issues.md', 'rest/repos/repos.md'],
}

function pagesToRender(generator: string, pages: Page[]): { render: Page[]; missing: string[] } {
  const pinned = PINNED_PAGES[generator] ?? []
  const byPath = new Map(pages.map((page) => [page.relativePath, page]))
  // Check pins in full-render mode too, so a PR that moves a pinned page fails before merge.
  const missing = pinned.filter((path) => !byPath.has(path))
  if (RENDER_ALL || !pinned.length) return { render: pages, missing }
  return { render: pinned.flatMap((path) => byPath.get(path) ?? []), missing }
}

describe('autogenerated docs render', () => {
  vi.setConfig({ testTimeout: 3 * 60 * 1000 })

  const autogeneratedPages = pageList.filter((page: Page) => page.autogenerated)
  const pagesByGenerator = Object.groupBy(autogeneratedPages, (page: Page) => page.autogenerated!)
  // Include pinned generators with no pages left, so their stale pins still fail.
  const generators = new Set([...Object.keys(pagesByGenerator), ...Object.keys(PINNED_PAGES)])
  const generatorCases = [...generators].map(
    (generator) => [generator, pagesByGenerator[generator] ?? []] as const,
  )

  test.each(generatorCases)('%s pages', async (generator, allPages) => {
    const { render: pages, missing } = pagesToRender(generator, allPages)
    expect(
      missing,
      `Pinned ${generator} pages not found. Update PINNED_PAGES in this file.`,
    ).toEqual([])
    // Each page must render with 200 OK and unique heading IDs.
    const errors = (
      await Promise.all(
        pages.map(async (page: Page) => {
          const url = page.permalinks[0].href
          // Slow autogenerated pages get retries to avoid false-positive failures.
          const res = await get(url, { retries: 3 })
          if (res.statusCode !== 200) {
            return `${res.statusCode} status error on ${url}`
          }
          // xmlMode is faster for this duplicate-ID scan.
          const $ = load(res.body, { xmlMode: true })
          const headingIDs = $('body')
            .find('h2, h3, h4, h5, h6')
            .map((_, el) => $(el).attr('id'))
            .get()
            .sort()
          const dupes = headingIDs.filter(
            (item: string, index: number) => headingIDs.indexOf(item) !== index,
          )
          if (dupes.length) {
            return `In ${url}, the following duplicate heading IDs were found: ${dupes.join(', ')}`
          }
        }),
      )
    ).filter(Boolean) as string[]
    expect(errors.length, errors.join('\n')).toBe(0)
  })

  const codeqlCliPath: string = JSON.parse(
    readFileSync('src/codeql-cli/lib/config.json', 'utf-8'),
  ).targetDirectory
  const restPath: string = JSON.parse(
    readFileSync('src/rest/lib/config.json', 'utf-8'),
  ).targetDirectory
  const ghappsPath: string = JSON.parse(
    readFileSync('src/github-apps/lib/config.json', 'utf-8'),
  ).targetDirectory
  // Only REST and CodeQL CLI pages get automated version frontmatter updates.
  // GitHub Apps pages apply to all versions and nest under REST, so exclude them.
  const filesWithAutoUpdatedVersions = autogeneratedPages.filter(
    (page: Page) =>
      (!page.fullPath.startsWith(ghappsPath) && page.fullPath.startsWith(restPath)) ||
      page.fullPath.startsWith(codeqlCliPath),
  )

  test.each(filesWithAutoUpdatedVersions)(
    'autogenerated page $fullPath does not use feature based versioning',
    (page: Page) => {
      expect(page.versions.feature).toBe(undefined)
    },
  )
})
